/* Product data stays in memory except explicit Gemini requests. */
'use strict';
const $=id=>document.getElementById(id),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const keyPool=new DSKeyPool();
const keyTestResults=new Map();let keyTestBusy=false;let aiStopRequested=false;let loadBusy=false;let loadedText='';let table=null,rows=[],baseTerms=[],page=0,activeIndex=null,revision=0,dirty=false,aiBusy=false;const PAGE_SIZE=20;
function notice(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error);}
function terms(){return [...new Set([...baseTerms,...DS.termsFrom($('blocked').value)])];}
function options(){if($('shipping').value===''||$('returns').value==='')throw Error('두 인상액을 입력해주세요.');return {terms:terms(),shipping:Number($('shipping').value),returns:Number($('returns').value),includeZero:$('zero').checked,position:$('position').value,keywordCount:Number($('keywordCount').value)};}
function invalidate(){if(!table)return;dirty=true;revision++;exportButtons();$('aiCheck').disabled=true;$('bulkApply').disabled=true;notice('입력 또는 규칙이 바뀌었습니다. 표를 다시 불러오거나 원본 기준으로 다시 계산해주세요.');}
function recalculate(){if(!table)return;if($('source').value!==loadedText)throw Error('원본 표가 변경되었습니다. 표를 다시 불러와주세요.');rows=DS.analyze(table,options());dirty=false;revision++;page=0;$('aiResults').replaceChildren();render();}
function load(){if(!$('source').value.trim())throw Error('붙여넣은 표가 없습니다. Excel에서 열 제목과 상품 행을 함께 복사해 위 입력란에 붙여넣어주세요.');if($('termText').value!==baseTerms.join('\n'))throw Error('변경한 금지어 목록의 ‘이 목록 적용’을 먼저 눌러주세요.');const parsed=DS.tableFrom($('source').value);const result=DS.analyze(parsed,options());table=parsed;loadedText=$('source').value;rows=result;dirty=false;revision++;page=0;$('search').value='';$('filter').value='all';$('aiResults').replaceChildren();render();notice(rows.length.toLocaleString()+'행을 불러왔습니다. '+(terms().length?'금지어를 제거하고 원본 기준으로 계산했습니다.':'금지어 목록을 먼저 불러와주세요.'));}
function filtered(){const query=DS.normalize($('search').value.trim()),filter=$('filter').value;return rows.filter(r=>!r.blank&&(!query||DS.normalize(r.code+' '+r.original).includes(query))&&(filter==='all'||filter==='fee'&&r.issues.length||r.status===filter));}
function render(){$('autoModel').disabled=aiBusy||keyTestBusy;$('model').disabled=aiBusy||keyTestBusy;const live=rows.filter(r=>!r.blank);$('total').textContent=live.length.toLocaleString();$('pending').textContent=live.filter(r=>r.status==='pending').length.toLocaleString();$('titles').textContent=live.filter(r=>(r.status==='approved'?r.approvedName:r.cleaned)!==r.original).length.toLocaleString();$('candidateSummary').textContent='추가 제안 대기 '+live.filter(r=>r.status==='pending').length.toLocaleString()+'개 · 추가 후보 없음 '+live.filter(r=>!r.candidates.length).length.toLocaleString()+'개 · 승인 '+live.filter(r=>r.status==='approved').length.toLocaleString()+'개 · 보류 '+live.filter(r=>r.status==='held').length.toLocaleString()+'개. 금지어 삭제와 배송비 계산은 전체 상품에 적용됩니다.';$('feeIssues').textContent=live.filter(r=>r.issues.length).length.toLocaleString();$('bulkApply').disabled=!table||dirty||!terms().length||!live.some(r=>r.status==='pending'&&r.keywordChecks.length===r.candidates.length);$('recalculate').disabled=!table;$('reviewLog').disabled=!table||dirty;$('aiCheck').disabled=!table||dirty||aiBusy||keyTestBusy;$('resultHint').textContent=table?`${table.headers.length}개 열 · ${rows.length.toLocaleString()}행 유지 · 금지어 ${terms().length.toLocaleString()}개 적용${dirty?' · 재계산 필요':''}`:'표를 불러오면 상품별 변경 내용이 여기에 표시됩니다.';
const list=filtered();page=Math.min(page,Math.max(0,Math.ceil(list.length/PAGE_SIZE)-1));const shown=list.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE);const shippingIndex=table?.names.indexOf('배송비'),returnIndex=table?.names.indexOf('반품배송비');
function feeCell(r,index){return r.source[index]===r.output[index]?escapeHTML(r.output[index]||'빈 셀'):`<span class="fee-old">${escapeHTML(r.source[index])}</span><span class="fee-new">${escapeHTML(r.output[index])}</span>`;}
$('rows').innerHTML=shown.length?shown.map(r=>`<tr><td><small>${r.index+2}행</small>${escapeHTML(r.code||'(코드 없음)')}</td><td>${escapeHTML(r.original)}${r.removed.length?`<span class="removed">삭제: ${escapeHTML(r.removed.join(', '))}</span>`:''}</td><td>${escapeHTML(r.status==='approved'?r.approvedName:r.cleaned)}${r.empty?'<span class="warning">삭제 후 상품명이 비었습니다. 수정 필요</span>':''}${r.status==='pending'?`<small>${r.keywordChecks.length?'AI 삽입 제안: '+escapeHTML(r.proposed):'AI가 삽입 위치를 판단하기 전입니다.'}</small>`:''}${r.keywordChecks.length?`<small>후보 검토: ${r.keywordChecks.map(c=>escapeHTML(c.keyword)+' · '+({no_obvious_issue:'뚜렷한 의심 없음',suspect:'의심 · 삽입 제외',uncertain:'불확실 · 삽입 제외'}[c.status])).join(' / ')}</small>`:r.candidates.length?'<small>추가 키워드 권리 검토 전</small>':'<small>'+escapeHTML(r.candidateReason)+'</small>'}<span class="status ${r.status}">${{pending:'추가 표현 검토 대기',approved:'사용자 수정 승인',held:'추가 제안 보류',cleaned:'목록 적용'}[r.status]}</span><span class="changed-keywords">키워드: ${escapeHTML(r.keywords||'(없음)')}</span></td><td>${feeCell(r,shippingIndex)}</td><td>${feeCell(r,returnIndex)}${r.issues.length?`<small class="warning">${escapeHTML(r.issues.join(' / '))}</small>`:''}</td><td><button class="secondary review-row" data-index="${r.index}" ${dirty?'disabled':''}>검토</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty"><span class="empty-grid">▦</span><strong>${table?'검색 조건에 맞는 상품이 없습니다':'아직 불러온 상품이 없습니다'}</strong><span>Excel 표를 붙여넣거나 예시로 시작하세요.</span></td></tr>`;
$('pageInfo').textContent=list.length?`${page*PAGE_SIZE+1}–${Math.min((page+1)*PAGE_SIZE,list.length)} / ${list.length.toLocaleString()}개 상품`:'0개 상품';$('prev').disabled=page===0;$('next').disabled=(page+1)*PAGE_SIZE>=list.length;exportButtons();}
function exportButtons(){const ready=!!table&&!dirty&&terms().length>0;const empty=rows.some(r=>!r.blank&&r.empty);$('copyBlock').disabled=!ready||empty;$('copyTitle').disabled=!ready||empty;$('copyKeywords').disabled=!ready;$('copyFees').disabled=!ready;$('download').disabled=!ready||empty;}
function checkExport(includeNames=true){if(!table||dirty||!terms().length)throw Error('표와 금지어를 불러오고 변경된 규칙을 다시 계산해주세요.');if(includeNames&&rows.some(r=>!r.blank&&r.empty))throw Error('금지어 삭제 후 이름이 빈 상품이 있습니다. 먼저 상품명을 수정해주세요.');}
function excelText(value){return /^[\s]*[=+@-]/.test(value)?"'"+value:value;}
async function copyData(data){const value=DS.stringify(data.map(row=>row.map(excelText)));try{await navigator.clipboard.writeText(value);notice(data.length.toLocaleString()+'행을 복사했습니다. 원래 Excel의 해당 열 첫 데이터 셀에 값으로 붙여넣으세요.');}catch{$('copyFallback').value=value;$('copyDialog').showModal();$('copyFallback').select();}}
function download(data,name,type='text/tab-separated-values;charset=utf-8'){const blob=new Blob(['\uFEFF',data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openReview(index){if(dirty)throw Error('변경된 규칙을 먼저 계산해주세요.');const row=rows[index];if(!row||row.blank)return;activeIndex=index;$('reviewId').textContent=`원본 ${index+2}행 · ${row.code||'코드 없음'}`;$('oldName').textContent=row.original;$('keywordName').textContent=row.keyword||'추가 후보 없음';$('newName').value=row.status==='approved'?row.approvedName:row.proposed;$('evidence').value=row.evidence||'';$('reviewError').textContent='';$('rowWarnings').textContent=[row.removed.length?'목록에서 삭제된 표현: '+row.removed.join(', '):'',row.empty?'금지어 삭제 후 이름이 비었습니다. 실제 상품에 맞는 이름을 입력해주세요.':'',...row.issues].filter(Boolean).join(' / ');$('rowDetails').textContent=table.headers.map((h,i)=>h+': '+row.source[i]).join('\n');renderCandidateChoices(row);$('reviewDialog').showModal();}
function setTerms(list){if(list.length>20000)throw Error('금지어는 최대 20,000개까지 지원합니다.');if(list.some(t=>t.length>200))throw Error('금지어는 한 항목에 200자 이하로 입력해주세요.');const next=[...new Set(list)];const nextRows=table?DS.analyze(table,{...options(),terms:[...new Set([...next,...DS.termsFrom($('blocked').value)])]}):null;baseTerms=next;$('termCount').textContent=baseTerms.length.toLocaleString()+'개 · 현재 브라우저';$('termText').value=baseTerms.join('\n');if(table){rows=nextRows;dirty=$('source').value!==loadedText;revision++;page=0;render();}notice(baseTerms.length.toLocaleString()+'개 금지어를 적용했습니다. 짧은 단어의 부분일치 삭제를 확인해주세요.');}
function run(action){return async(...args)=>{try{await action(...args);}catch(e){notice(e.message||'작업 중 오류가 발생했습니다.',true);}};}
function loadStatus(message,state){$('loadStatus').textContent=message;$('loadStatus').dataset.state=state;}
async function loadWithFeedback(){if(loadBusy)return;loadBusy=true;const button=$('load');button.disabled=true;button.textContent='표 처리 중…';button.setAttribute('aria-busy','true');$('recalculate').disabled=true;loadStatus('처리 중 · 표 형식 확인, 금지어 제거, 배송비 계산을 진행합니다. 큰 표는 잠시 기다려주세요.','loading');try{await new Promise(resolve=>setTimeout(resolve,50));load();const count=rows.filter(r=>!r.blank).length;const message='불러오기 완료 · '+count.toLocaleString()+'개 상품 / '+table.headers.length+'개 열 · '+(terms().length?'금지어 '+terms().length.toLocaleString()+'개 적용':'금지어 목록 미등록 — 금지어 목록을 먼저 불러와주세요.');loadStatus(message,'success');notice(message+' 추가 키워드는 검토 후 반영됩니다.');$('resultsSection').scrollIntoView({behavior:'smooth',block:'start'});$('resultsSection').focus({preventScroll:true});}catch(e){const message='불러오기 실패 · '+(e.message||'표 형식을 확인해주세요.');loadStatus(message,'error');notice(message,true);$('loadStatus').scrollIntoView({behavior:'smooth',block:'nearest'});}finally{loadBusy=false;button.disabled=false;button.textContent='표 불러오기';button.removeAttribute('aria-busy');$('recalculate').disabled=!table;}}
$('load').onclick=loadWithFeedback;$('recalculate').onclick=loadWithFeedback;
$('source').addEventListener('input',invalidate);for(const id of ['shipping','returns','zero','position','keywordCount','blocked'])$(id).addEventListener('input',invalidate);
$('restoreTerms').onclick=run(()=>setTerms([...DSForbiddenTerms]));
$('useTerms').onclick=run(()=>setTerms(DS.termsFrom($('termText').value)));$('termText').addEventListener('input',()=>{if(table)invalidate();});
$('termFile').onchange=run(async()=>{const file=$('termFile').files[0];if(!file)return;if(file.size>15000000)throw Error('파일은 15MB 이하만 지원합니다.');const list=/\.txt$/i.test(file.name)?DS.termsFrom(await file.text()):await readForbiddenWorkbook(file);setTerms(list);});
$('sample').onclick=run(()=>{const samples=[{'상품코드':'DEMO-001','상품명':'최고 주방 수납 바구니','키워드':'세계최초,정리함,주방용','배송비':'3000','반품배송비':'6000'},{'상품코드':'DEMO-002','상품명':'책상 케이블 정리 클립','키워드':'선정리,데스크용','배송비':'0','반품배송비':'3,000원'},{'상품코드':'DEMO-003','상품명':'욕실 수납 선반','키워드':'정리용,욕실용','배송비':'무료','반품배송비':''}];if(!baseTerms.length)setTerms(['최고','세계최초']);$('source').value=DS.stringify([DS.HEADERS,...samples.map(s=>DS.HEADERS.map(h=>s[h]||''))]);load();notice('가상 예시 3개입니다. 내장 금지어가 적용됩니다. 실제 작업 전 상품 표를 교체하세요.');});
for(const id of ['search','filter'])$(id).addEventListener('input',()=>{page=0;render();});$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};$('rows').onclick=run(e=>{const button=e.target.closest('.review-row');if(button)openReview(Number(button.dataset.index));});
$('closeDialog').onclick=()=>$('reviewDialog').close();$('closeCopy').onclick=()=>$('copyDialog').close();$('hold').onclick=()=>{rows[activeIndex]={...rows[activeIndex],status:'held',approvedName:undefined,evidence:$('evidence').value,empty:!rows[activeIndex].cleaned.trim()};revision++;$('reviewDialog').close();render();};
$('reviewForm').onsubmit=e=>{e.preventDefault();try{if(dirty)throw Error('규칙이 바뀌었습니다. 다시 계산해주세요.');rows[activeIndex]=DS.approve(rows[activeIndex],$('newName').value,$('evidence').value,terms());revision++;$('reviewDialog').close();render();}catch(error){$('reviewError').textContent=error.message;}};

$('copyBlock').onclick=run(async()=>{checkExport();await copyData(DS.exportBlock(table,rows));});
$('copyTitle').onclick=run(async()=>{checkExport();const ix=table.names.indexOf('상품명');await copyData(DS.exportRows(table,rows).map(r=>[r[ix]]));});
$('copyKeywords').onclick=run(async()=>{checkExport(false);const ix=table.names.indexOf('키워드');await copyData(DS.exportRows(table,rows).map(r=>[r[ix]]));});
$('copyFees').onclick=run(async()=>{checkExport(false);const a=table.names.indexOf('배송비'),b=table.names.indexOf('반품배송비');if(b!==a+1)throw Error('배송비 두 열이 인접하지 않습니다. 전체 TSV에서 각각 복사해주세요.');await copyData(DS.exportRows(table,rows).map(r=>[r[a],r[b]]));});
$('download').onclick=run(()=>{checkExport();download(DS.stringify([table.headers,...DS.exportRows(table,rows)].map(r=>r.map(excelText))),'eilav-edited.tsv');notice('전체 표를 받았습니다. Excel의 텍스트 가져오기에서 상품코드 등 식별자 열을 텍스트로 지정하세요.');});
$('reviewLog').onclick=run(()=>{if(dirty)throw Error('다시 계산한 뒤 기록을 받으세요.');download(DS.stringify([['원본행','상품코드','원본상품명','금지어제거후','최종상품명','최종키워드','삭제표현','상태','배송비확인','검토메모','확인시각','추가키워드검토'],...rows.filter(r=>!r.blank).map(r=>[r.index+2,r.code,r.original,r.cleaned,r.status==='approved'?r.approvedName:r.cleaned,r.keywords,r.removed.join(', '),r.status,r.issues.join(' / '),r.evidence,r.reviewedAt||'',JSON.stringify(r.keywordChecks)])].map(r=>r.map(v=>excelText(String(v??''))))),'eilav-review.tsv');});
$('aiStop').onclick=()=>{aiStopRequested=true;$('aiStop').disabled=true;$('aiStatus').textContent='중지 요청됨 · 현재 묶음 결과를 받은 뒤 멈춥니다.';};
$('aiCheck').onclick=run(async()=>{
 if(aiBusy||keyTestBusy)return;
 if(!table||dirty||!terms().length)throw Error('먼저 표와 금지어를 불러와 계산해주세요.');
 
 if(!keyPool.summary().length)throw Error('Gemini API 키를 먼저 등록해주세요.');
 const selected=DSBatch.pending(rows);if(!selected.length){$('aiStatus').textContent='모든 추가 후보의 AI 검토가 완료됐거나 추가 후보가 없습니다.';return;}
 const ix=n=>table.names.indexOf(n),items=selected.map(r=>({id:r.index,title:r.cleaned,candidates:r.candidates,brand:(r.source[ix('브랜드')]||'').slice(0,200),category:(r.source[ix('카테고리')]||'').slice(0,200)}));
 let expectedRevision=revision,completed=0,requestModel='';const automatic=$('autoModel').checked,manualModel=$('model').value.trim(),position=$('position').value,fallback=$('keyFallback').checked;
 aiBusy=true;aiStopRequested=false;$('aiStop').disabled=false;$('aiProgress').max=items.length;$('aiProgress').value=0;$('aiResults').replaceChildren();render();renderKeys();
 try{const outcome=await DSBatch.run({items,valid:()=>revision===expectedRevision&&!dirty,stopped:()=>aiStopRequested,onRetry:count=>{$('aiStatus').textContent=count+'개 묶음의 응답 형식을 복구하기 위해 5개씩 나눠 다시 요청합니다. 완료 결과는 유지됩니다.';},
 request:batch=>keyPool.execute(async key=>{if(!requestModel){requestModel=await DSGemini.resolveModel({key,model:manualModel,automatic});showModel(requestModel,automatic);}return DSGemini.check({key,model:requestModel,items:batch,onUsage:metadata=>keyPool.recordUsage(key,metadata)});},{fallback}),
 apply:results=>{const next=results.map(result=>DS.applyKeywordReview(rows[result.id],result.keywords,position));for(const row of next)rows[row.index]=row;revision++;expectedRevision=revision;renderKeys();render();},
 progress:(done,total)=>{completed=done;$('aiProgress').value=done;$('aiStatus').textContent='이번 실행 '+done.toLocaleString()+' / '+total.toLocaleString()+'개 완료 · 전체 미검토 '+DSBatch.pending(rows).length.toLocaleString()+'개';}
 });$('aiStatus').textContent=(outcome.stopped?'중지됨':'전체 AI 위치 판단 완료')+' · 이번 실행 '+completed.toLocaleString()+'개 완료. '+(outcome.stopped?'시작 / 이어하기를 누르면 남은 상품부터 처리합니다.':'의심·불확실하거나 자연스러운 삽입 위치가 없는 후보를 제외했습니다. 일괄 적용을 누르면 AI 삽입 결과를 반영합니다.');
 }catch(e){$('aiStatus').textContent='검토 중지 · '+completed.toLocaleString()+'개 완료한 결과는 유지됩니다. '+e.message+' 원인을 해결한 뒤 시작 / 이어하기를 누르세요.';notice('전체 검토가 중지됐습니다. Gemini 영역에서 진행 상황과 오류를 확인해주세요.',true);
 }finally{aiBusy=false;$('aiStop').disabled=true;renderKeys();render();}
});
function renderCandidateChoices(row){const parent=$('candidateChecks');parent.replaceChildren();for(const keyword of row.candidates){const check=row.keywordChecks.find(c=>c.keyword===keyword),excluded=row.excludedKeywords.includes(keyword);const label=document.createElement('label');label.className='check';const box=document.createElement('input');box.type='checkbox';box.value=keyword;box.checked=!excluded;box.disabled=excluded;box.onchange=()=>{const selected=[...parent.querySelectorAll('input:checked')].map(x=>x.value);$('newName').value=$('position').value==='ai'?DS.placeAIKeywords(row.cleaned,row.keywordChecks.filter(c=>selected.includes(c.keyword))):DS.placeKeywords(row.cleaned,selected,$('position').value);};const text=document.createElement('span');text.textContent=keyword+' · '+(check?({no_obvious_issue:'일반 지식상 뚜렷한 의심 없음',suspect:'의심되어 제외',uncertain:'불확실하여 제외'}[check.status])+' / '+check.reason+(check.afterWord===null?' · 삽입 제외':Number.isInteger(check.afterWord)?' · 원본 '+check.afterWord+'번째 단어 뒤':''):'검토 전 · 직접 확인 또는 Gemini 검토 필요');label.append(box,text);parent.append(label);}}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_editor_summary',description:'현재 표의 행 수, 금지어 수, 수정 대기 수를 읽습니다. 개인정보나 API 키를 반환하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({rows:rows.length,forbiddenTerms:terms().length,pending:rows.filter(r=>r.status==='pending').length,dirty})},{name:'stage_excel_table',description:'Excel TSV 표를 편집 화면에 불러와 금지어 제거 및 배송비 변경을 준비합니다. 원본 Excel을 수정하거나 결과를 전송하지 않습니다.',inputSchema:{type:'object',properties:{tsv:{type:'string'}},required:['tsv'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(typeof input?.tsv!=='string')throw Error('tsv 문자열이 필요합니다.');const checked=DS.tableFrom(input.tsv);DS.analyze(checked,options());$('source').value=input.tsv;load();return{rows:rows.length,columns:table.headers.length};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
setTerms([...DSForbiddenTerms]);
notice(DSForbiddenTerms.length.toLocaleString()+'개 내장 금지어를 자동 적용했습니다. Excel 표를 붙여넣어 시작하세요.');
render();

function renderKeys(){try{keyPool.save(localStorage);$('keyStorageStatus').textContent='이 브라우저에 저장됨 · 다시 열면 자동 복원됩니다.';}catch{$('keyStorageStatus').textContent='브라우저 저장 실패 · 현재 페이지에서만 사용할 수 있습니다.';}const list=$('keyList');list.replaceChildren();for(const key of keyPool.summary()){const div=document.createElement('div');div.className='key-row';const text=document.createElement('span');text.textContent=key.label+' · '+key.project+' · '+key.mask+' · '+({ready:'사용 가능',quota:'프로젝트 한도 중지',invalid:'키 권한 확인'}[key.status])+' · 요청 '+key.usage.requests.toLocaleString()+'회 · 응답 '+key.usage.responses.toLocaleString()+'회 · 토큰 '+key.usage.total.toLocaleString()+' (입력 '+key.usage.input.toLocaleString()+' / 출력 '+key.usage.output.toLocaleString()+')';div.append(text);const use=document.createElement('button');use.className='secondary';use.textContent=key.active?'선택됨':'선택';use.disabled=key.active||aiBusy||keyTestBusy;use.onclick=run(()=>{keyPool.select(key.id);renderKeys();});div.append(use);if(key.status!=='ready'){const reset=document.createElement('button');reset.className='secondary';reset.textContent='확인 후 중지 해제';reset.disabled=aiBusy||keyTestBusy;reset.onclick=run(()=>{keyPool.reset(key.project);renderKeys();});div.append(reset);}const remove=document.createElement('button');remove.className='secondary';remove.textContent='삭제';remove.disabled=aiBusy||keyTestBusy;remove.onclick=run(()=>{keyPool.remove(key.id);renderKeys();});div.append(remove);const test=document.createElement('button');test.className='secondary';test.textContent='연결 테스트';test.disabled=aiBusy||keyTestBusy;test.onclick=()=>testKey(key.id);div.append(test);const status=document.createElement('span');status.className='muted';status.setAttribute('role','status');status.textContent=keyTestResults.get(key.id)||'아직 테스트하지 않음';div.append(status);list.append(div);}}
$('addKey').onclick=run(()=>{keyPool.add($('keyLabel').value,$('keyProject').value,$('apiKey').value);$('apiKey').value='';$('keyLabel').value='';renderKeys();notice('키를 등록했습니다. 아래 브라우저 저장 상태를 확인해주세요.');});

$('bulkApply').onclick=run(()=>{if(!table||dirty||!terms().length)throw Error('먼저 표와 수정 규칙을 적용해주세요.');const candidates=filtered().filter(r=>r.status==='pending'&&!r.empty&&($('position').value!=='ai'||r.keywordChecks.length===r.candidates.length));if(!candidates.length)throw Error('적용할 제안이 없습니다. AI 위치 모드에서는 먼저 전체 AI 검토를 실행해주세요.');const approved=candidates.map(r=>DS.approve(r,r.proposed,'일괄 적용',terms()));for(const row of approved)rows[row.index]=row;revision++;render();notice(approved.length.toLocaleString()+'개 상품의 추가 표현을 반영했습니다.');});

try{keyPool.restore(localStorage);renderKeys();}catch{$('keyStorageStatus').textContent='저장된 키를 복원하지 못했습니다. 키를 다시 등록해주세요.';}

async function testKey(id){if(aiBusy||keyTestBusy)return;const automatic=$('autoModel').checked;let model=automatic?'자동 선택':$('model').value.trim();keyTestBusy=true;keyTestResults.set(id,model+' · 연결 테스트 중…');renderKeys();render();try{const result=await keyPool.test(id,async key=>{model=await DSGemini.resolveModel({key,model,automatic});showModel(model,automatic);return DSGemini.testConnection({key,model,onUsage:metadata=>keyPool.recordUsage(key,metadata)});});keyTestResults.set(id,'연결 성공 · '+result.model+' · '+(result.elapsedMs/1000).toFixed(1)+'초 · '+new Date().toLocaleTimeString('ko-KR'));}catch(e){keyTestResults.set(id,'연결 실패 · '+model+' · '+(e.status?'HTTP '+e.status+' · ':'')+e.message);}finally{keyTestBusy=false;renderKeys();render();}}

function showModel(model,automatic){$('model').value=model;$('modelStatus').textContent=(automatic?'자동 선택':'직접 지정')+' · '+model+' · 이번 실행 동안 유지됩니다. 자동 선택은 다음 시작 시 다시 확인합니다.';}
$('autoModel').onchange=()=>{$('model').readOnly=$('autoModel').checked;$('modelStatus').textContent=$('autoModel').checked?'다음 시작 시 사용 가능한 안정 버전 모델을 다시 확인합니다.':'Google에서 사용할 수 있는 모델 ID를 직접 입력하세요.';};
